-- CCN Mock Exam Day 7 (29 Oct 2026): new 200-question paper
-- Sections: A ICT/computer (1–40), B research & statistics (41–80), C entrepreneurship & management (81–120),
-- D nursing process & theories (121–160), E topics not used on earlier days (161–200).
-- The questions are added as hidden exam-only copies (they do not appear in the practice app),
-- then Day 7's question list is replaced. Students who already started Day 7 keep their old questions.
set lock_timeout = '5s';
begin;
create temporary table d7new (n int primary key, topic text, q text, opts jsonb, ans_idx int, exp text, category text) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + d.n, d.topic, 'CCN Mock Exam — Day 7 (29 Oct 2026)', d.q, d.opts, d.ans_idx, d.exp, d.category, '📝', false
from d7new d
where not exists (select 1 from public.questions x where x.source = 'CCN Mock Exam — Day 7 (29 Oct 2026)' and x.q = d.q);
update public.exam_exams
   set question_ids = (select array_agg(x.id order by d.n) from d7new d join public.questions x on x.source = 'CCN Mock Exam — Day 7 (29 Oct 2026)' and x.q = d.q)
 where title = 'CCN Mock Exam — Day 7 of 7 (200 Questions)';
select title, cardinality(question_ids) as questions_in_exam from public.exam_exams where title = 'CCN Mock Exam — Day 7 of 7 (200 Questions)';
commit;
