insert into d7new values
(1, 'Nursing Informatics & ICT', 'The physical and tangible parts of a computer are called ____', '["Values", "Hardware", "Software", "Tables"]'::jsonb, 1, 'The physical, tangible components of a computer are called hardware.', 'Nursing Informatics & ICT'),
(2, 'Nursing Informatics & ICT', 'What is Computer Memory (Storage devices)?', '["They are devices that command the computer on how to execute programs to solve problems", "They are devices that perform all the processing in the computer.", "They are devices that are used for storing data and information permanently or temporarily", "They are devices that convert information from the form that the computer understands to a form that humans can understand."]'::jsonb, 2, 'Storage devices are used to hold data/information either temporarily or permanently.', 'Nursing Informatics & ICT'),
(3, 'Nursing Informatics & ICT', 'Software designed and installed on a computer intended to solve specific problems or perform particular tasks is called?', '["Application software", "Open Source Software", "Utility", "Spreadsheet"]'::jsonb, 0, 'Software built for a specific task/problem is application software.', 'Nursing Informatics & ICT'),
(4, 'Nursing Informatics & ICT', 'System software is a software that ____', '["is used in making presentations", "is used for data analysis", "is used to manage health information of patients", "manages the resources on the computer and enable the hardware to function properly"]'::jsonb, 3, 'System software manages computer resources and enables hardware to function properly.', 'Nursing Informatics & ICT'),
(5, 'Nursing Informatics & ICT', 'The devices that give out data and information from the computer are called ____', '["Universal Serial Bus", "Network Topology", "Sink/Receiver", "Output devices"]'::jsonb, 3, 'Devices that give out data/information from the computer are output devices.', 'Nursing Informatics & ICT'),
(6, 'Nursing Informatics & ICT', 'The devices that send data and control signals INTO the computer are called ____', '["Network", "Input devices", "Operating System", "Arithmetic Unit"]'::jsonb, 1, 'Devices sending data/control signals into the computer are input devices.', 'Nursing Informatics & ICT'),
(7, 'Nursing Informatics & ICT', 'A network in which all the communicating computers are of the same or similar capacity is called a ____?', '["Mainframe network", "Server-client network", "Cloud computing Network", "Peer to peer network"]'::jsonb, 3, 'A network of similarly capable computers communicating as equals is a peer-to-peer network.', 'Nursing Informatics & ICT'),
(8, 'Nursing Informatics & ICT', 'In a Computer Network the means of connection is ____?', '["Speaker", "Receiver/sink", "Sender/source", "Medium/channel"]'::jsonb, 3, 'The medium/channel is the means of connection in a computer network.', 'Nursing Informatics & ICT'),
(9, 'Nursing Informatics & ICT', 'What is a Computer Network?', '["A Computer Network is the interconnection of two or more computers or computing devices through a medium for the purpose of sharing resources.", "A Computer Network is the interconnection of two or more agents to achieve a goal", "A Computer Network is the interconnection people to increase productivity", "A Computer Network is the interconnection of schools to give information"]'::jsonb, 0, 'A computer network is the interconnection of two or more computing devices to share resources.', 'Nursing Informatics & ICT'),
(10, 'Nursing Informatics & ICT', 'Which of these best defines a computer?', '["A computer is an electronic communication device.", "A computer is a music playing calculation device.", "A computer is an electronic device that accepts data processes data stores data and gives out information.", "A computer is an education device for presentation."]'::jsonb, 2, 'A computer is defined as an electronic device that accepts, processes, stores, and outputs data/information.', 'Nursing Informatics & ICT'),
(11, 'Nursing Informatics & ICT', 'What does a spreadsheet software like Microsoft Excel allow users to do?', '["Create, organize, and analyze data in a tabular format", "Create and edit images", "Manage emails", "Browse the internet"]'::jsonb, 0, 'Excel allows creating, organising, and analysing data in a tabular (spreadsheet) format.', 'Nursing Informatics & ICT'),
(12, 'Nursing Informatics & ICT', 'The location of a resource on the internet is given by its?', '["ICQ", "Protocol", "E-mail address", "URL"]'::jsonb, 3, 'A resource''s internet location is given by its URL.', 'Nursing Informatics & ICT'),
(13, 'Nursing Informatics & ICT', 'Which of the following is not considered hardware?', '["Hard disk", "Keyboard", "CPU", "Operating system"]'::jsonb, 3, 'An operating system is software, not hardware.', 'Nursing Informatics & ICT'),
(14, 'Nursing Informatics & ICT', '____ is a transmission medium that is most appropriate to carry data in a computer network that is exposed to electrical interferences', '["Coaxial cable", "Unshielded twisted pair", "Optical fiber", "Microwave"]'::jsonb, 2, 'Optical fibre is immune to electrical interference, unlike copper-based media.', 'Nursing Informatics & ICT'),
(15, 'Nursing Informatics & ICT', 'A collection of hyperlinked documents on the internet forms the', '["Hypertext markup language", "World Wide Web (WWW)", "E-mail system", "Mailing list"]'::jsonb, 1, 'Hyperlinked documents across the internet make up the World Wide Web.', 'Nursing Informatics & ICT'),
(16, 'Nursing Informatics & ICT', 'The Central Processing Unit (CPU) of a computer is primarily responsible for:', '["Permanent data storage only", "Executing instructions and processing data", "Displaying output on the monitor only", "Providing internet connectivity only"]'::jsonb, 1, 'The CPU is the computer''s ''brain'' — it fetches, decodes and executes instructions, performing the actual data processing.', 'Nursing Informatics & ICT'),
(17, 'Nursing Informatics & ICT', 'Batch processing, as a method of file processing, is best described as:', '["Collecting and processing a group of transactions together at a scheduled time", "A method used only for video files", "Processing that requires no computer at all", "Processing transactions immediately as they occur, one at a time"]'::jsonb, 0, 'Batch processing accumulates data over a period and processes it together at a set time, rather than immediately as each transaction occurs.', 'Nursing Informatics & ICT'),
(18, 'Nursing Informatics & ICT', 'A master file in a computerised records system typically contains:', '["Only images and video files", "Relatively permanent, core reference data about an entity (e.g. patient demographic records)", "Only system error logs", "Temporary data deleted after each session"]'::jsonb, 1, 'Master files hold relatively stable, core data (such as patient demographics) that is referenced and updated over time, unlike temporary transaction files.', 'Nursing Informatics & ICT'),
(19, 'Nursing Informatics & ICT', 'Data standardization and classification in nursing informatics (e.g. using NANDA, NIC, NOC) primarily helps to:', '["Increase paperwork with no benefit", "Enable consistent communication, data comparison and research across different settings", "Make nursing documentation ambiguous and inconsistent", "Replace the need for any nursing assessment"]'::jsonb, 1, 'Standardised nursing languages/classifications allow consistent terminology, enabling comparison, communication and research across different institutions and systems.', 'Nursing Informatics & ICT'),
(20, 'Nursing Informatics & ICT', 'USB flash drives and optical disks (CD/DVD) are examples of:', '["Primary memory (RAM)", "Input devices only", "Secondary/portable storage devices", "Output devices only"]'::jsonb, 2, 'USB flash drives and optical disks are portable secondary storage media used to store and transfer data outside the computer''s main memory.', 'Nursing Informatics & ICT'),
(21, 'Nursing Informatics & ICT', 'A Hospital Information System (HIS) is best defined as:', '["An integrated system that manages a hospital''s clinical, administrative and financial information", "A single stand-alone computer used only by the IT department", "A manual paper filing cabinet", "A type of medical imaging machine"]'::jsonb, 0, 'A HIS integrates clinical, administrative and financial data management across the hospital into one coordinated system.', 'Nursing Informatics & ICT'),
(22, 'Nursing Informatics & ICT', 'Protecting electronic access to client data primarily relies on which of the following measures?', '["Printing all records to avoid computer use entirely", "Leaving all records openly accessible to any staff member for convenience", "Disabling all data backups", "User authentication (passwords/logins), access controls and audit trails"]'::jsonb, 3, 'Controlled access via authentication, role-based permissions and audit trails is a core safeguard for protecting confidential electronic client data.', 'Nursing Informatics & ICT'),
(23, 'Nursing Informatics & ICT', 'Index-sequential file organisation allows records to be accessed:', '["Only by physically searching every record one by one with no index", "Both sequentially and directly via an index, combining the benefits of both methods", "Only in the exact order they were originally entered, with no shortcuts", "Never — it is a theoretical method with no real use"]'::jsonb, 1, 'Index-sequential organisation maintains an index that allows direct access to specific records while still supporting sequential processing.', 'Nursing Informatics & ICT'),
(24, 'Nursing Informatics & ICT', 'A hospital''s electronic health record system experiences a temporary outage. The nurse''s most appropriate immediate action is to:', '["Stop all patient care until the system returns", "Discharge all patients immediately", "Guess at patient information from memory with no documentation", "Follow the unit''s downtime/contingency procedure (e.g. paper documentation) to ensure continuity of safe care"]'::jsonb, 3, 'Hospitals maintain downtime/contingency procedures (often paper-based) for EHR outages, ensuring safe continuity of care and documentation until the system is restored.', 'Nursing Informatics & ICT'),
(25, 'Nursing Informatics & ICT', 'The main purpose of barcode medication administration (BCMA) is to:', '["Replace the need for a medication administration record", "Track staff attendance", "Speed up medication rounds regardless of accuracy", "Verify the five rights of medication administration and reduce medication errors"]'::jsonb, 3, 'BCMA scans patient and medication barcodes to confirm the right patient, drug, dose, route, and time, reducing administration errors.', 'Nursing Informatics & ICT'),
(26, 'Nursing Informatics & ICT', 'Tele-ICU (remote ICU monitoring) primarily allows:', '["Only administrative record-keeping", "Replacement of ventilator alarms", "Elimination of bedside nurses", "Remote specialists to monitor and support ICU care across multiple sites"]'::jsonb, 3, 'Tele-ICU connects remote intensivists/specialists to bedside teams via cameras and data feeds, extending expert oversight to ICUs that may lack on-site specialists around the clock.', 'Nursing Informatics & ICT'),
(27, 'Nursing Informatics & ICT', 'A clinical decision support system (CDSS) in an EHR is designed to:', '["Automatically treat the patient without clinician input", "Only manage billing", "Replace nursing assessment", "Alert clinicians to potential issues such as drug interactions or abnormal values"]'::jsonb, 3, 'CDSS tools generate alerts (e.g. drug-drug interactions, allergy warnings, abnormal lab flags) to support — not replace — clinical judgement.', 'Nursing Informatics & ICT'),
(28, 'Nursing Informatics & ICT', 'Health Level Seven (HL7) standards exist primarily to support:', '["Hospital parking systems", "Interoperability and standardised exchange of health information between systems", "Physical security of hospital buildings", "Only nursing schedules"]'::jsonb, 1, 'HL7 standards define how clinical and administrative data are structured and exchanged so that different health information systems can communicate with each other.', 'Nursing Informatics & ICT'),
(29, 'Nursing Informatics & ICT', 'Nursing informatics is best defined as the specialty that:', '["Integrates nursing science with information and computer science to manage and communicate data, information, and knowledge", "Focuses only on hospital billing software", "Replaces the need for clinical nursing skills", "Is only relevant to IT department staff"]'::jsonb, 0, 'Nursing informatics integrates nursing science, computer science, and information science to support clinical decision-making and improve patient care through data and technology.', 'Nursing Informatics & ICT'),
(30, 'Nursing Informatics & ICT', 'Two-factor authentication improves EHR security by:', '["Requiring a second independent verification step beyond just a password", "Disabling password requirements", "Allowing shared generic logins", "Requiring only a username"]'::jsonb, 0, 'Two-factor authentication adds a second verification layer (e.g. a code sent to a device) beyond the password, making unauthorised access significantly harder.', 'Nursing Informatics & ICT'),
(31, 'Nursing Informatics & ICT', 'Encrypting patient data primarily protects against:', '["Slower data transmission", "Unauthorised parties reading intercepted or stolen data", "Hardware failure", "Loss of internet connectivity"]'::jsonb, 1, 'Encryption converts data into unreadable code without the correct key, protecting patient information if it is intercepted, lost, or stolen.', 'Nursing Informatics & ICT'),
(32, 'Nursing Informatics & ICT', 'In data transfer process, what does FTP stand for?', '["File transmission protocol", "File transfer Protocol", "File transfer program", "File transfer protection"]'::jsonb, 1, 'FTP is File Transfer Protocol, a standard way of moving files between computers over a network.', 'Nursing Informatics & ICT'),
(33, 'Nursing Informatics & ICT', 'The four main functional components of a standard computer are:', '["Input, process, output and memory (storage)", "Laptop, desktop, tablet and hand-held", "Keyboard, mouse, monitor and CPU", "Hardware, software, system apps and applications"]'::jsonb, 0, 'A computer''s four main functional components are input, processing, output and storage (memory).', 'Nursing Informatics & ICT'),
(34, 'Nursing Informatics & ICT', 'According to size, computers are classified as:', '["Large, ultra-large, small and compact", "Laptop, desktop and hand-held", "Big-scale and small-scale", "Super, mainframe, mini and micro computers"]'::jsonb, 3, 'By size, computers are classified as super, mainframe, mini and micro computers.', 'Nursing Informatics & ICT'),
(35, 'Nursing Informatics & ICT', 'Computer software is classified into:', '["Special, general and specific packages", "Personal and industrial software", "Word, PowerPoint and Excel", "System, application and utility software"]'::jsonb, 3, 'Software is broadly system software (including utilities) and application software.', 'Nursing Informatics & ICT'),
(36, 'Nursing Informatics & ICT', 'Which one is NOT an input device?', '["Monitor", "Mouse", "Scanner", "Keyboard"]'::jsonb, 0, 'A monitor is an output device. Mouse, keyboard and scanner are input devices.', 'Nursing Informatics & ICT'),
(37, 'Nursing Informatics & ICT', 'Which of the following is NOT a network topology?', '["Bus", "Star", "Peer to Peer", "Ring"]'::jsonb, 2, 'Star, ring, and bus are all physical or logical network topologies describing how devices are arranged and connected. Peer to peer describes a network architecture or relationship model, not a topology.', 'Nursing Informatics & ICT'),
(38, 'Nursing Informatics & ICT', 'A nurse is teaching a group of nursing students about the history of computers. Which generation of computers is characterized by the use of vacuum tubes?', '["Second Generation", "Third Generation", "First Generation", "Fourth Generation"]'::jsonb, 2, 'The First Generation of computers, from 1940 to 1956, were characterized by the use of bulky and energy-inefficient vacuum tubes for circuitry. Second Generation computers used transistors, Third Generation used integrated circuits, and Fourth Generation used microprocessors.', 'Nursing Informatics & ICT'),
(39, 'Nursing Informatics & ICT', 'Which of the following units of data is the largest?', '["Gigabyte (GB)", "Megabyte (MB)", "Kilobyte (KB)", "Terabyte (TB)"]'::jsonb, 3, 'A Terabyte is the largest unit listed, equal to about one trillion bytes. The order from smallest to largest is: Kilobyte (about one thousand bytes), Megabyte (about one million bytes), Gigabyte (about one billion bytes), and Terabyte.', 'Nursing Informatics & ICT'),
(40, 'Nursing Informatics & ICT', 'A nurse is explaining units of data to a colleague. The smallest unit of data in a computer is a:', '["Byte", "Bit", "Megabyte", "Kilobyte"]'::jsonb, 1, 'A bit (binary digit) is the most basic unit of information in computing and is a one or a zero. A byte is a group of 8 bits. The other options are larger units of data.', 'Nursing Informatics & ICT'),
(41, 'Research Methods & Statistics', 'Research usually starts with a problem and ends with:', '["Conclusions and recommendations (dissemination of findings)", "A literature review", "A hypothesis", "Data collection"]'::jsonb, 0, 'Research starts with a problem and ends with conclusions, recommendations and dissemination of findings.', 'Research & Nursing Process'),
(42, 'Research Methods & Statistics', 'In research, the term "universe" refers to the:', '["Study setting", "Entire population", "Research instrument", "Sample"]'::jsonb, 1, 'The "universe" is the whole population: all the units of interest.', 'Research & Nursing Process'),
(43, 'Research Methods & Statistics', 'All of the following are methods (sources) of problem-solving knowledge EXCEPT:', '["Tradition", "Assessment", "Voices of authority", "Logical reasoning"]'::jsonb, 1, 'Tradition, authority and logical reasoning are sources of knowledge or problem-solving. "Assessment" is not one of them.', 'Research & Nursing Process'),
(44, 'Research Methods & Statistics', 'Which step of the research process cuts across all the other steps?', '["Literature review", "Research variables", "Problem identification", "Hypothesis"]'::jsonb, 0, 'The literature review runs through the whole research process, from framing the problem to discussing findings.', 'Research & Nursing Process'),
(45, 'Research Methods & Statistics', 'All the following are probability sampling methods EXCEPT:', '["Stratified sampling", "Simple random sampling", "Quota sampling", "Cluster sampling"]'::jsonb, 2, 'Quota sampling is non-probability. Stratified, cluster and simple random sampling are probability methods.', 'Research & Nursing Process'),
(46, 'Research Methods & Statistics', 'The measure of location that divides a data set into two equal parts is the:', '["Range", "Mode", "Mean", "Median"]'::jsonb, 3, 'The median divides an ordered data set into two equal halves.', 'Research & Nursing Process'),
(47, 'Research Methods & Statistics', 'Plagiarism means:', '["Literary appreciation", "Literary reference", "Literary competence", "Literary theft"]'::jsonb, 3, 'Plagiarism is literary theft: presenting others'' work as your own.', 'Research & Nursing Process'),
(48, 'Research Methods & Statistics', 'An acceptable reliability coefficient is:', '["1.01 to 1.05", "Greater than 0.6–0.7", "1.05 to 1.09", "Greater than 2.0"]'::jsonb, 1, 'Cronbach''s alpha (reliability) ranges from 0 to 1. Values of about 0.6–0.7 or more are usually accepted.', 'Research & Nursing Process'),
(49, 'Research Methods & Statistics', 'Quantitative research is characterized by', '["In-depth exploration of lived experiences using words and narratives without numbers", "Avoidance of any form of measurement", "Collection and statistical analysis of numerical data to test hypotheses or describe variables objectively", "Reliance solely on the researcher''s personal opinion"]'::jsonb, 2, 'Quantitative research emphasizes objective measurement and statistical, mathematical analysis of numerical data.', 'Research & Nursing Process'),
(50, 'Research Methods & Statistics', 'Qualitative research is best suited to studies that aim to', '["Test a hypothesis using a large randomly selected sample and inferential statistics", "Measure the precise incidence rate of a disease in a population", "Determine the statistical correlation between two numerically measured variables", "Explore and understand the meaning, experiences, and perspectives of individuals in depth"]'::jsonb, 3, 'Qualitative research explores phenomena in depth through non-numerical data such as words, focusing on meaning and lived experience rather than statistical measurement.', 'Research & Nursing Process'),
(51, 'Research Methods & Statistics', 'A study that describes the characteristics of ventilator-associated pneumonia rates in an ICU without manipulating any variable is an example of', '["Quasi-experimental research", "True experimental research", "Descriptive research", "Historical research"]'::jsonb, 2, 'Descriptive research simply observes and describes characteristics of a phenomenon as it naturally occurs, without manipulating variables.', 'Research & Nursing Process'),
(52, 'Research Methods & Statistics', 'Historical research in nursing is primarily concerned with', '["Describing current staffing patterns in an ICU", "Predicting future patient outcomes using statistical models", "Systematically collecting and evaluating data related to past events to understand their influence on the present", "Manipulating an intervention to observe its immediate effect"]'::jsonb, 2, 'Historical research systematically examines and interprets past events, records, and documents to understand their significance and influence on present nursing practice.', 'Research & Nursing Process'),
(53, 'Research Methods & Statistics', 'A research purpose focused on determining whether an increase in nurse-to-patient ratio causes a reduction in medication errors is best described as', '["Exploratory research with no measurable variables", "Purely descriptive research", "Explanatory (causal) research", "Historical research"]'::jsonb, 2, 'Explanatory research seeks to establish cause-and-effect relationships between variables, such as staffing ratio and medication error rates.', 'Research & Nursing Process'),
(54, 'Research Methods & Statistics', '''Validity'' in research refers to', '["The extent to which an instrument accurately measures what it is intended to measure", "The statistical significance level chosen by the researcher", "The extent to which an instrument gives consistent results on repeated use", "The total number of subjects included in a study"]'::jsonb, 0, 'Validity concerns whether an instrument truly measures the concept it claims to measure, distinct from reliability, which concerns consistency.', 'Research & Nursing Process'),
(55, 'Research Methods & Statistics', '''Operational definition'' of a variable refers to', '["The name of the statistical test applied to the variable", "A dictionary definition of the term unrelated to the study context", "A precise description of how a variable will be measured or manipulated in a specific study", "The theoretical meaning of a concept found in textbooks only"]'::jsonb, 2, 'An operational definition specifies exactly how a variable will be measured, observed, or manipulated within the context of a particular study, ensuring clarity and replicability.', 'Research & Nursing Process'),
(56, 'Research Methods & Statistics', 'The term ''extraneous variable'' refers to a variable that', '["Always improves the accuracy of the study findings", "Refers only to variables measured using qualitative methods", "Is not the focus of the study but may influence the dependent variable and confound the results if not controlled", "Is deliberately manipulated by the researcher as the main variable of interest"]'::jsonb, 2, 'Extraneous (confounding) variables are variables outside the researcher''s primary interest that can influence the outcome and must be controlled to avoid distorting results.', 'Research & Nursing Process'),
(57, 'Research Methods & Statistics', 'A primary source in a literature review refers to', '["An original report of a study written by the researcher(s) who actually conducted it", "A newspaper article about a general health topic", "A textbook summarizing several other people''s research", "An encyclopedia entry with no citations"]'::jsonb, 0, 'A primary source is a first-hand account of research or theory written by those who conducted the original work, as opposed to a secondary source that summarizes or interprets others'' work.', 'Research & Nursing Process'),
(58, 'Research Methods & Statistics', 'A secondary source in a literature review is best exemplified by', '["The raw dataset collected by the researcher", "A review article or textbook chapter that summarizes and synthesizes findings from several original studies", "The original journal article reporting a specific randomized controlled trial", "An unpublished doctoral thesis reporting the author''s own study"]'::jsonb, 1, 'Secondary sources interpret, summarize, or comment on primary research (e.g., textbooks, review articles) rather than presenting original findings first-hand.', 'Research & Nursing Process'),
(59, 'Research Methods & Statistics', 'A researcher studies the effect of a structured early mobilization protocol on the length of ICU stay. In this study, the independent variable is', '["The name of the hospital", "The structured early mobilization protocol", "The length of ICU stay", "The age of the patients"]'::jsonb, 1, 'The early mobilization protocol is the intervention being manipulated by the researcher, making it the independent variable; length of ICU stay is the outcome (dependent variable).', 'Research & Nursing Process'),
(60, 'Research Methods & Statistics', 'In a study examining whether hand hygiene compliance among ICU nurses affects the rate of hospital-acquired infections, the dependent variable is', '["The type of hospital where the study is conducted", "The rate of hospital-acquired infections", "Hand hygiene compliance", "The number of nurses working in the unit"]'::jsonb, 1, 'The rate of hospital-acquired infections is the outcome being measured, making it the dependent variable, while hand hygiene compliance is the independent variable presumed to influence it.', 'Research & Nursing Process'),
(61, 'Research Methods & Statistics', 'A ''discrete variable'' is one that', '["Can only take on distinct, separate values, typically whole numbers, such as the number of children a person has", "Always refers to a qualitative characteristic that cannot be counted", "Can take on any value along a continuum, including fractions and decimals", "Cannot be measured under any circumstances"]'::jsonb, 0, 'A discrete variable takes on distinct, countable values (e.g., number of ICU admissions), unlike a continuous variable which can take any value within a range.', 'Research & Nursing Process'),
(62, 'Research Methods & Statistics', 'Research questions are generally used instead of hypotheses when', '["The researcher wants to test a precise cause-and-effect relationship with an experimental design", "The study must always involve statistical hypothesis testing", "Qualitative research is strictly prohibited from using questions", "The study is exploratory or descriptive in nature and there is insufficient existing knowledge to predict a specific relationship"]'::jsonb, 3, 'Research questions are typically favored in exploratory, descriptive, or qualitative studies where too little is known to justify predicting a specific directional relationship.', 'Research & Nursing Process'),
(63, 'Research Methods & Statistics', 'A study comparing infection rates between an ICU that adopted a new hand hygiene protocol and a similar ICU that continued standard practice, without randomly assigning patients or units to groups, is an example of a', '["Phenomenological design", "Historical design", "Quasi-experimental design", "True experimental design"]'::jsonb, 2, 'Because units (not individual subjects) were not randomly assigned to intervention and comparison groups, this reflects a quasi-experimental (non-randomized) design.', 'Research & Nursing Process'),
(64, 'Research Methods & Statistics', 'A cross-sectional study design involves', '["Collecting data from a population or sample at a single point in time", "Following the same group of subjects over an extended period with repeated measurements", "Manipulating the independent variable with random assignment", "Reviewing historical documents only"]'::jsonb, 0, 'Cross-sectional designs capture data at one specific point in time, providing a ''snapshot'' of the population, as opposed to longitudinal designs that follow subjects over time.', 'Research & Nursing Process'),
(65, 'Research Methods & Statistics', 'A phenomenological research design, a type of qualitative design, is primarily used to', '["Explore and describe the lived experiences and meanings that individuals attach to a particular phenomenon", "Manipulate an independent variable under controlled experimental conditions", "Statistically test hypotheses using large, randomly selected samples", "Analyze numerical trends in large population datasets"]'::jsonb, 0, 'Phenomenology, a qualitative approach, seeks to understand and describe the lived experiences and subjective meanings individuals assign to a phenomenon.', 'Research & Nursing Process'),
(66, 'Research Methods & Statistics', 'An ''ethnographic'' research design focuses on', '["Studying the culture, beliefs, and practices of a particular group through immersion and observation over time", "Testing the statistical significance of an intervention using a control group", "Randomly assigning subjects to experimental conditions", "Reviewing quantitative survey data collected via mailed questionnaires only"]'::jsonb, 0, 'Ethnography is a qualitative design in which the researcher immerses in and observes a cultural group to understand its beliefs, values, and practices.', 'Research & Nursing Process'),
(67, 'Research Methods & Statistics', 'A ''sampling frame'' is best described as', '["A synonym for the research design", "The final report describing the study''s results", "The theoretical framework guiding the study", "A complete list of all elements or subjects in the accessible population from which a sample will be drawn"]'::jsonb, 3, 'A sampling frame is the actual list (e.g., a patient register or staff roster) from which individual sample elements are selected.', 'Research & Nursing Process'),
(68, 'Research Methods & Statistics', 'Systematic sampling involves', '["Choosing subjects purely based on the researcher''s personal judgment of who is ''typical''", "Selecting every kth element from a list after a random starting point", "Allowing existing participants to recruit further participants", "Selecting subjects based only on their convenient availability"]'::jsonb, 1, 'Systematic sampling selects every kth element from an ordered sampling frame, beginning from a randomly chosen starting point.', 'Research & Nursing Process'),
(69, 'Research Methods & Statistics', 'Snowball sampling is a technique especially useful for studying', '["Extremely large populations with a complete and accessible sampling frame", "Populations where random selection using computer software is straightforward", "Only populations with fewer than five known members in existence", "Hard-to-reach or hidden populations, where existing participants refer the researcher to other potential participants they know"]'::jsonb, 3, 'Snowball sampling relies on referrals from initial participants to reach further participants, making it especially valuable for hidden or hard-to-access populations.', 'Research & Nursing Process'),
(70, 'Research Methods & Statistics', 'A researcher studying illicit drug users, a population without an available formal list or registry, asks initial participants to refer other drug users they know. This sampling technique is called', '["Systematic sampling", "Stratified random sampling", "Quota sampling", "Snowball sampling"]'::jsonb, 3, 'Recruiting participants for a hidden or hard-to-locate population through referrals from existing participants is the defining characteristic of snowball sampling.', 'Research & Nursing Process'),
(71, 'Research Methods & Statistics', 'The "null hypothesis" (H0) states that:', '["There is a significant difference or relationship between the variables studied", "The research design used was invalid", "The sample size used was too small to be valid", "There is no significant difference or relationship between the variables being studied"]'::jsonb, 3, 'The null hypothesis is the default position that there is no true difference or relationship, which statistical tests attempt to reject or fail to reject.', 'Research & Nursing Process'),
(72, 'Research Methods & Statistics', 'Which scale of measurement classifies data into categories with no inherent order, such as blood group (A, B, AB, O)?', '["Interval", "Nominal", "Ratio", "Ordinal"]'::jsonb, 1, 'Nominal scales simply label or categorise data with no meaningful order or numeric relationship between categories.', 'Research & Nursing Process'),
(73, 'Research Methods & Statistics', 'A patient''s pain level rated as "mild, moderate, severe" is an example of which scale of measurement?', '["Ratio", "Nominal", "Ordinal", "Interval"]'::jsonb, 2, 'Ordinal scales rank categories in a meaningful order, but the intervals between ranks are not necessarily equal.', 'Research & Nursing Process'),
(74, 'Research Methods & Statistics', 'Body temperature measured in degrees Celsius is an example of which scale of measurement?', '["Ratio", "Interval", "Ordinal", "Nominal"]'::jsonb, 1, 'Celsius temperature has equal intervals between units but no true zero point (0 degrees C is not the absence of temperature), making it an interval scale.', 'Research & Nursing Process'),
(75, 'Research Methods & Statistics', 'Which measure of central tendency is most appropriate for a data set with extreme outlier values (a highly skewed distribution)?', '["Standard deviation", "Mean", "Median", "Mode"]'::jsonb, 2, 'The median is less affected by extreme outliers than the mean, making it the more appropriate measure of central tendency for skewed distributions.', 'Research & Nursing Process'),
(76, 'Research Methods & Statistics', 'The "standard deviation" is a measure of:', '["The most frequently occurring value", "The central tendency of a data set", "The relationship between two variables", "The average distance or spread of individual values from the mean"]'::jsonb, 3, 'Standard deviation quantifies how much individual data values typically deviate from the mean, indicating the spread or variability of the data.', 'Research & Nursing Process'),
(77, 'Research Methods & Statistics', 'A "Type I error" in hypothesis testing occurs when:', '["The wrong statistical test is applied to the data", "A false null hypothesis is not rejected", "The sample size chosen is too large", "A true null hypothesis is incorrectly rejected (a false positive)"]'::jsonb, 3, 'A Type I error is a false positive: concluding there is a significant effect or difference when, in reality, none exists.', 'Research & Nursing Process'),
(78, 'Research Methods & Statistics', 'A "Type II error" in hypothesis testing occurs when:', '["A false null hypothesis is incorrectly accepted or not rejected (a false negative)", "The alternative hypothesis is proven true", "The p-value is exactly 0.05", "A true null hypothesis is rejected"]'::jsonb, 0, 'A Type II error is a false negative: failing to detect a real effect or difference that actually exists in the population.', 'Research & Nursing Process'),
(79, 'Research Methods & Statistics', 'Which statistical test is commonly used to compare the means of two independent groups, such as two treatment groups?', '["Pearson correlation coefficient", "Student''s t-test", "Frequency distribution table", "Chi-square test"]'::jsonb, 1, 'The independent-samples t-test is used to compare the means of two separate groups to see if they differ significantly.', 'Research & Nursing Process'),
(80, 'Research Methods & Statistics', 'When comparing the means of more than two groups simultaneously (e.g., three different ICU sedation protocols), which statistical test is most appropriate?', '["Chi-square test", "Analysis of Variance (ANOVA)", "A simple frequency count", "Paired t-test"]'::jsonb, 1, 'ANOVA is designed to compare means across three or more groups simultaneously while controlling the overall risk of a Type I error.', 'Research & Nursing Process'),
(81, 'Entrepreneurship & Management', 'Entrepreneurship is best defined as:', '["Saving money in a fixed deposit account", "Inheriting a family business without taking part in managing it", "Working as a salaried employee in a government hospital", "The process of identifying an opportunity and organising resources to create a new venture, accepting the risks in return for profit or social value"]'::jsonb, 3, 'An entrepreneur spots an opportunity, gathers the resources (money, people, equipment) to pursue it, and bears the risk of the venture in return for profit or social value. Salaried employment and passive saving involve no venture creation or risk-taking.', 'Ethics, Law & Management'),
(82, 'Entrepreneurship & Management', 'A nurse who starts her own private home-care service for elderly patients discharged from hospital is an example of:', '["Delegation", "Intrapreneurship", "Moonlighting", "Nurse entrepreneurship"]'::jsonb, 3, 'Nurse entrepreneurship is a nurse owning and running an independent business that provides nursing services (e.g. home care, health education, a private clinic). Intrapreneurship is innovation inside an employer''s organisation.', 'Ethics, Law & Management'),
(83, 'Entrepreneurship & Management', 'A nurse who designs and leads a new discharge-teaching service inside the hospital where she is employed is practising:', '["Outsourcing", "Sole proprietorship", "Intrapreneurship", "Franchising"]'::jsonb, 2, 'Intrapreneurship means behaving like an entrepreneur within an existing organisation: creating new services or improvements while remaining an employee, using the organisation''s resources.', 'Ethics, Law & Management'),
(84, 'Entrepreneurship & Management', 'Which characteristic is MOST typical of a successful entrepreneur?', '["Avoiding every form of risk", "Willingness to take calculated risks", "Depending on others for every decision", "Resistance to change"]'::jsonb, 1, 'Entrepreneurs take calculated (moderate, well-analysed) risks. Other key traits are initiative, creativity, self-confidence, persistence and openness to change.', 'Ethics, Law & Management'),
(85, 'Entrepreneurship & Management', 'In a SWOT analysis, ''Strengths'' and ''Weaknesses'' refer to:', '["Internal factors within the business", "External factors in the market", "Government policies only", "Competitors'' future plans"]'::jsonb, 0, 'SWOT = Strengths and Weaknesses (internal: skills, resources, reputation) and Opportunities and Threats (external: market, policy, competition, economy).', 'Ethics, Law & Management'),
(86, 'Entrepreneurship & Management', 'In a SWOT analysis for a private nursing clinic, a new government policy expanding health-insurance coverage to more families would be classified as:', '["An opportunity", "A strength", "A weakness", "A threat"]'::jsonb, 0, 'It is external to the clinic and could increase demand and the ability of clients to pay, so it is an opportunity.', 'Ethics, Law & Management'),
(87, 'Entrepreneurship & Management', 'A written document that describes a new venture''s goals, target market, operations, management and financial projections is called a:', '["Memorandum of understanding", "Duty roster", "Business plan", "Job description"]'::jsonb, 2, 'A business plan sets out what the business will do, who it serves, how it will operate, who will manage it and how it will be financed. Lenders and investors usually ask for one.', 'Ethics, Law & Management'),
(88, 'Entrepreneurship & Management', 'The FIRST step in starting a new business is usually to:', '["Buy equipment", "Print business cards", "Identify a business idea/opportunity and assess its feasibility", "Employ staff"]'::jsonb, 2, 'Start by identifying a genuine need or opportunity and testing whether it is feasible (demand, cost, competition, regulation) before committing money to equipment, staff or publicity.', 'Ethics, Law & Management'),
(89, 'Entrepreneurship & Management', 'A feasibility study is carried out mainly to:', '["Calculate staff salaries only", "Determine whether a proposed business idea is practical and likely to succeed financially", "Advertise the business", "Recruit employees"]'::jsonb, 1, 'A feasibility study examines market demand, costs, technical and legal requirements and expected returns to decide whether the idea is worth pursuing.', 'Ethics, Law & Management'),
(90, 'Entrepreneurship & Management', 'A business owned and managed by one person who bears unlimited liability for its debts is a:', '["Cooperative society", "Sole proprietorship", "Limited liability company", "Partnership"]'::jsonb, 1, 'In a sole proprietorship the owner and the business are legally the same, so the owner''s personal assets can be used to pay business debts (unlimited liability).', 'Ethics, Law & Management'),
(91, 'Entrepreneurship & Management', 'The main advantage of a limited liability company over a sole proprietorship is that:', '["Profits never have to be shared", "The owners'' personal assets are protected; their liability is limited to what they invested", "It cannot be sued", "It does not need to be registered"]'::jsonb, 1, 'A limited liability company is a separate legal entity, so shareholders can lose only what they invested. It must be registered and can sue and be sued in its own name.', 'Ethics, Law & Management'),
(92, 'Entrepreneurship & Management', 'In Nigeria, business names and companies are registered with the:', '["Nursing and Midwifery Council of Nigeria", "Central Bank of Nigeria", "Corporate Affairs Commission (CAC)", "NAFDAC"]'::jsonb, 2, 'The Corporate Affairs Commission registers business names, companies and incorporated trustees under the Companies and Allied Matters Act (CAMA 2020). The NMCN regulates nurses, not businesses.', 'Ethics, Law & Management'),
(93, 'Entrepreneurship & Management', 'Money and other resources used to start and run a business are called:', '["Turnover", "Profit", "Dividend", "Capital"]'::jsonb, 3, 'Capital is the money and assets invested to start and operate a business. Profit is what remains after costs; turnover is total sales; a dividend is profit paid to shareholders.', 'Ethics, Law & Management'),
(94, 'Entrepreneurship & Management', 'Profit is calculated as:', '["Capital plus total revenue", "Total revenue plus total costs", "Total revenue minus total costs", "Total costs minus total revenue"]'::jsonb, 2, 'Profit = total revenue (income from sales) − total costs (fixed + variable). If costs exceed revenue the result is a loss.', 'Ethics, Law & Management'),
(95, 'Entrepreneurship & Management', 'The rent for a clinic''s premises, which stays the same whether 5 or 50 clients are seen in a month, is an example of a:', '["Variable cost", "Revenue", "Fixed cost", "Dividend"]'::jsonb, 2, 'Fixed costs (rent, salaries, insurance) do not change with the volume of services provided in the short term.', 'Ethics, Law & Management'),
(96, 'Entrepreneurship & Management', 'Disposable gloves and dressings, whose use rises with the number of clients seen, are examples of:', '["Variable costs", "Fixed costs", "Owner''s equity", "Capital assets"]'::jsonb, 0, 'Variable costs change in direct proportion to the volume of services delivered: more clients, more consumables.', 'Ethics, Law & Management'),
(97, 'Entrepreneurship & Management', 'The break-even point is the level of sales at which:', '["Total revenue equals total costs, so there is neither profit nor loss", "Tax becomes payable", "The business makes its maximum profit", "The business must close down"]'::jsonb, 0, 'At break-even, revenue exactly covers fixed plus variable costs. Sales above this point produce profit; below it, a loss.', 'Ethics, Law & Management'),
(98, 'Entrepreneurship & Management', 'A home-care nurse has fixed costs of ₦60,000 a month. Each visit costs ₦2,000 in supplies and transport, and she charges ₦5,000 per visit. How many visits a month does she need to break even?', '["12 visits", "40 visits", "30 visits", "20 visits"]'::jsonb, 3, 'Break-even = fixed costs ÷ (price − variable cost per visit) = 60,000 ÷ (5,000 − 2,000) = 60,000 ÷ 3,000 = 20 visits.', 'Ethics, Law & Management'),
(99, 'Entrepreneurship & Management', 'The ''4 Ps'' of the marketing mix are:', '["Purpose, Process, Product, Profit", "Plan, People, Profit, Policy", "Patients, Providers, Payment, Premises", "Product, Price, Place, Promotion"]'::jsonb, 3, 'The marketing mix: Product (the service), Price (what it costs), Place (where/how it is delivered) and Promotion (how people learn about it).', 'Ethics, Law & Management'),
(100, 'Entrepreneurship & Management', 'Choosing a specific group of clients for a service (for example, families of patients discharged on home oxygen) is called:', '["Diversification", "Liquidation", "Auditing", "Market segmentation and targeting"]'::jsonb, 3, 'Segmentation divides the market into groups with similar needs; targeting selects the group(s) the business will serve and designs the service for them.', 'Ethics, Law & Management'),
(101, 'Entrepreneurship & Management', 'Which source of start-up finance does NOT have to be repaid with interest?', '["A bank overdraft", "The owner''s personal savings (owner''s equity)", "A microfinance loan", "A bank loan"]'::jsonb, 1, 'Personal savings invested by the owner become owner''s equity, with no interest or repayment schedule. Loans and overdrafts are debts that attract interest.', 'Ethics, Law & Management'),
(102, 'Entrepreneurship & Management', 'Keeping accurate records of all income and expenses in a small nursing business is important mainly to:', '["Know the financial position, guide decisions and meet tax and legal obligations", "Avoid paying staff", "Impress clients", "Replace the business plan"]'::jsonb, 0, 'Good bookkeeping shows whether the business is making a profit, supports planning and borrowing, and is needed for tax returns and audits.', 'Ethics, Law & Management'),
(103, 'Entrepreneurship & Management', 'An entrepreneur''s ability to recognise an unmet need in the community that could become a business is called:', '["Opportunity recognition", "Bureaucracy", "Stagnation", "Risk aversion"]'::jsonb, 0, 'Opportunity recognition is noticing a gap between what people need and what is currently available, and seeing how to fill it.', 'Ethics, Law & Management'),
(104, 'Entrepreneurship & Management', 'Social entrepreneurship differs from purely commercial entrepreneurship mainly because its main goal is to:', '["Maximise profit for the owner only", "Avoid paying taxes", "Compete only with government hospitals", "Solve a social or health problem, with any profit reinvested in the mission"]'::jsonb, 3, 'Social entrepreneurs use business methods to tackle social problems (e.g. maternal health education, affordable community care); success is measured by social impact as well as financial sustainability.', 'Ethics, Law & Management'),
(105, 'Entrepreneurship & Management', 'When a nurse entrepreneur advertises her services, which practice is MOST consistent with professional ethics?', '["Truthful advertising with no false claims of cure or guaranteed results", "Using clients'' photographs without consent", "Criticising named colleagues to win their clients", "Promising guaranteed cures to attract clients"]'::jsonb, 0, 'The nursing code of conduct requires honesty: advertising must be accurate, must not promise cures or mislead, must respect colleagues and must protect client confidentiality.', 'Ethics, Law & Management'),
(106, 'Entrepreneurship & Management', 'The following are qualities of a good leader EXCEPT:', '["Pride", "Vision", "Integrity", "Knowledge"]'::jsonb, 0, 'Integrity, vision and knowledge are leadership qualities. Pride is not.', 'Ethics, Law & Management'),
(107, 'Entrepreneurship & Management', '"The organisation is a complex whole with parts working together like the human body." Which theory fits this statement?', '["Human relations theory", "Classical theory", "Humanist theory", "Systems theory"]'::jsonb, 3, 'Systems theory sees the organisation as a complex whole of interdependent parts, like the human body.', 'Ethics, Law & Management'),
(108, 'Entrepreneurship & Management', 'The theory that individuals compare their job inputs and outcomes with others'' to remove inequities is:', '["Reinforcement theory", "Efficacy theory", "Maslow''s hierarchy", "Equity theory"]'::jsonb, 3, 'Equity theory (Adams): people compare their inputs and outcomes with others'' and act to remove perceived inequity.', 'Ethics, Law & Management'),
(109, 'Entrepreneurship & Management', 'A leadership style that allows the opinion of the majority of group members is:', '["Democratic", "Bureaucratic", "Autocratic", "Laissez-faire"]'::jsonb, 0, 'Democratic leaders involve the group and go with majority opinion.', 'Ethics, Law & Management'),
(110, 'Entrepreneurship & Management', 'The unwritten personal expectations an employee brings to an organisation are called the:', '["Official contract", "Job description", "Psychological contract", "Personal ambition"]'::jsonb, 2, 'The psychological contract is the unwritten set of personal expectations an employee brings to the organisation.', 'Ethics, Law & Management'),
(111, 'Entrepreneurship & Management', 'The purchase of a new ventilator should be included in the:', '["Operating budget", "Salary budget", "Capital budget", "Revenue budget"]'::jsonb, 2, 'Major equipment purchases like a ventilator are capital expenditures, funded through the capital budget.', 'Ethics, Law & Management'),
(112, 'Entrepreneurship & Management', 'FIFO is mainly used to:', '["Increase waste", "Delay procurement", "Increase stock", "Prevent expiry of supplies"]'::jsonb, 3, 'FIFO ensures older stock is used before newer stock, helping prevent items expiring unused.', 'Ethics, Law & Management'),
(113, 'Entrepreneurship & Management', 'A medication error is detected and corrected before it reaches the patient. This event is classified as a:', '["Near miss", "Never event", "Adverse event", "Sentinel event"]'::jsonb, 0, 'A near miss is an error that is caught before it reaches the patient, so no harm occurs. An adverse event causes harm; a sentinel event causes death or serious harm; a never event is a serious, wholly preventable incident. Near misses should still be reported so the system can learn.', 'Ethics, Law & Management'),
(114, 'Entrepreneurship & Management', 'Which quality tool is commonly used to identify the underlying causes of a problem?', '["Duty roster", "Fishbone (Ishikawa) diagram", "Organizational chart", "Leave register"]'::jsonb, 1, 'The fishbone (Ishikawa) diagram is a structured tool for identifying the underlying causes of a problem.', 'Ethics, Law & Management'),
(115, 'Entrepreneurship & Management', 'A nurse manager observes that staff members are reluctant to report medication errors due to fear of punishment. Which culture should be promoted?', '["Just culture", "Competitive culture", "Blame culture", "Punitive culture"]'::jsonb, 0, 'A just culture, focused on system learning rather than blame, encourages honest reporting of medication errors.', 'Ethics, Law & Management'),
(116, 'Entrepreneurship & Management', 'Frederick Winslow Taylor''s mechanism of scientific management includes:', '["Scientific task setting", "Planning the task", "Standardisation of tools and equipment", "All of the above"]'::jsonb, 3, 'Taylor''s mechanism includes scientific task setting, work planning, standardisation of tools, scientific selection and training, and differential pay.', 'Ethics, Law & Management'),
(117, 'Entrepreneurship & Management', 'Henri Fayol was a:', '["Social scientist", "Accountant", "Mining engineer", "Production engineer"]'::jsonb, 2, 'Henri Fayol was a French mining engineer who became managing director of a mining company.', 'Ethics, Law & Management'),
(118, 'Entrepreneurship & Management', 'What is the full form of MBO?', '["Method By Objective", "Method By opportunity", "Management By Objectives", "Management By Opportunity"]'::jsonb, 2, 'MBO is Management By Objectives.', 'Ethics, Law & Management'),
(119, 'Entrepreneurship & Management', '____ involves harmony and team spirit among employees.', '["Standardisation", "Esprit de corps", "Order", "Discipline"]'::jsonb, 1, 'Esprit de corps promotes team spirit and harmony.', 'Ethics, Law & Management'),
(120, 'Entrepreneurship & Management', 'According to Kurt Lewin, which of the following is not a stage in the change process?', '["Unfreezing", "Restraining", "Changing", "Refreezing"]'::jsonb, 1, 'Lewin''s change model is unfreezing, changing (moving) and refreezing. Restraining forces belong to his force-field analysis.', 'Ethics, Law & Management'),
(121, 'Nursing Process & Nursing Theories', 'General Systems Theory, foundational to many nursing conceptual models, is most closely associated with which theorist?', '["Virginia Henderson", "Abraham Maslow", "Ludwig von Bertalanffy", "Florence Nightingale"]'::jsonb, 2, 'Ludwig von Bertalanffy, a biologist, formulated General Systems Theory, which was later adapted by nurse theorists such as Neuman and Rogers to describe the person as a system interacting with the environment.', 'Research & Nursing Process'),
(122, 'Nursing Process & Nursing Theories', 'In systems theory, ''entropy'' refers to:', '["The boundary that separates a system from its environment", "The tendency of a system to gain increasing order and energy over time", "The tendency of a system toward disorder, disorganization, and eventual energy depletion", "The exchange of information between two systems"]'::jsonb, 2, 'Entropy describes a system''s natural tendency toward disorganization and breakdown; nursing interventions often aim to counter entropy by supporting the client''s stability (negentropy).', 'Research & Nursing Process'),
(123, 'Nursing Process & Nursing Theories', 'A nurse opens the windows of a patient''s room to allow fresh air circulation and moves the patient''s bed closer to a window for natural sunlight. This action best reflects which nursing theorist''s framework?', '["Dorothea Orem", "Florence Nightingale", "Sister Callista Roy", "Marjory Gordon"]'::jsonb, 1, 'Ventilation and exposure to natural light were central environmental factors in Nightingale''s theory, which held that fresh air and sunlight promote the body''s reparative processes.', 'Research & Nursing Process'),
(124, 'Nursing Process & Nursing Theories', 'Virginia Henderson defined the unique function of the nurse as assisting the individual, sick or well, in the performance of activities contributing to health, recovery, or:', '["A peaceful death", "Financial independence", "Employment reintegration", "Permanent institutionalization"]'::jsonb, 0, 'Henderson''s classic definition states the nurse assists the individual in activities contributing to health, its recovery, or a peaceful death, that the person would perform unaided if they had the necessary strength, will, or knowledge.', 'Research & Nursing Process'),
(125, 'Nursing Process & Nursing Theories', 'According to Henderson, the overarching goal of nursing assistance is to help the client achieve:', '["Total reliance on family caregivers", "A prolonged hospital stay to ensure thorough recovery", "Independence as rapidly as possible", "Complete and permanent dependence on the healthcare team"]'::jsonb, 2, 'A central tenet of Henderson''s framework is that nursing care should be delivered in a manner that helps the client regain independence as rapidly as possible, rather than fostering unnecessary dependence.', 'Research & Nursing Process'),
(126, 'Nursing Process & Nursing Theories', 'According to Orem, a ''self-care deficit'' exists when:', '["The nurse is unavailable to provide any physical care", "The client''s self-care agency (ability) is insufficient to meet the therapeutic self-care demand", "The client has more self-care ability than is needed", "The client''s family refuses to participate in care"]'::jsonb, 1, 'A self-care deficit occurs when the client''s capability to perform self-care (self-care agency) is not sufficient to meet the existing therapeutic self-care demand, indicating a need for nursing intervention.', 'Research & Nursing Process'),
(127, 'Nursing Process & Nursing Theories', 'Orem categorized self-care requisites into three types. Which of the following correctly lists them?', '["Universal, developmental, and health-deviation self-care requisites", "Physiological, psychological, and spiritual self-care requisites", "Primary, secondary, and tertiary self-care requisites", "Focal, contextual, and residual self-care requisites"]'::jsonb, 0, 'Orem identified universal self-care requisites (common to all humans, e.g., air, water, food), developmental self-care requisites (associated with developmental processes/life events), and health-deviation self-care requisites (arising from illness or injury).', 'Research & Nursing Process'),
(128, 'Nursing Process & Nursing Theories', 'Orem described three nursing systems used to address self-care deficits. In which system does the nurse perform all of the client''s therapeutic self-care because the client is totally unable to do so?', '["Wholly compensatory nursing system", "Partly compensatory nursing system", "Supportive-educative nursing system", "Independent nursing system"]'::jsonb, 0, 'The wholly compensatory system is used when the client cannot perform any self-care activities (e.g., an unconscious or completely immobile patient), so the nurse compensates entirely for the client''s inability.', 'Research & Nursing Process'),
(129, 'Nursing Process & Nursing Theories', 'A client who is fully capable of performing self-care but needs teaching and guidance to safely administer insulin at home would be best supported using which of Orem''s nursing systems?', '["Supportive-educative (supportive-developmental) nursing system", "Wholly compensatory nursing system", "Partly compensatory nursing system", "Restorative nursing system"]'::jsonb, 0, 'The supportive-educative system is used when the client can perform self-care but requires guidance, teaching, or emotional support to develop the necessary knowledge or skills, such as learning insulin self-administration.', 'Research & Nursing Process'),
(130, 'Nursing Process & Nursing Theories', 'Rogers'' principle of ''helicy'' refers to:', '["The exact repetition of identical life patterns over time", "The continuous, innovative, unpredictable, increasingly diverse nature of the mutual human-environment field process, evolving in a probabilistic, non-repeating manner", "The idea that only physical, three-dimensional space governs human experience", "The classification of illness into discrete, static stages"]'::jsonb, 1, 'Helicy describes the continuous, probabilistic, and increasingly diverse nature of change in the human-environment field, evolving innovatively rather than in a fixed, repeating pattern.', 'Research & Nursing Process'),
(131, 'Nursing Process & Nursing Theories', 'In Neuman''s model, the ''basic core structure'' refers to:', '["The outermost, accordion-like protective buffer against stressors", "The client''s coping mechanisms only", "A ranked list of psychosocial needs", "The central, innermost structure containing basic survival factors common to the species, such as genetic features and organ strength"]'::jsonb, 3, 'The basic core structure is the innermost ring in Neuman''s model, containing the essential survival factors — such as normal temperature range, genetic structure, and organ strength — common to the human species.', 'Research & Nursing Process'),
(132, 'Nursing Process & Nursing Theories', 'Neuman classifies stressors into three types based on their relationship to the client system. Which of the following correctly identifies them?', '["Focal, contextual, and residual stressors", "Intrapersonal, interpersonal, and extrapersonal stressors", "Universal, developmental, and health-deviation stressors", "Primary, secondary, and tertiary stressors"]'::jsonb, 1, 'Neuman categorizes stressors as intrapersonal (occurring within the person, e.g., an autoimmune response), interpersonal (occurring between individuals, e.g., role expectations), and extrapersonal (occurring outside the person, e.g., financial or environmental circumstances).', 'Research & Nursing Process'),
(133, 'Nursing Process & Nursing Theories', 'Neuman describes three levels of prevention as intervention. Which level is aimed at strengthening the flexible line of defense BEFORE a stressor invades the client system?', '["Quaternary prevention", "Secondary prevention", "Primary prevention", "Tertiary prevention"]'::jsonb, 2, 'Primary prevention in Neuman''s model occurs before a stressor has invaded the system, aiming to reduce the possibility of encountering the stressor or to strengthen the flexible line of defense, such as through immunization or health teaching.', 'Research & Nursing Process'),
(134, 'Nursing Process & Nursing Theories', 'In Roy''s model, the stimulus that is immediately confronting the person and requires the most immediate attention is called the:', '["Compensatory stimulus", "Residual stimulus", "Contextual stimulus", "Focal stimulus"]'::jsonb, 3, 'The focal stimulus is the internal or external stimulus most immediately confronting the person, to which the person must adapt.', 'Research & Nursing Process'),
(135, 'Nursing Process & Nursing Theories', 'Roy''s model describes two major internal control processes, or coping subsystems, that a person uses to adapt to stimuli. What are they?', '["The wholly compensatory and partly compensatory subsystems", "The self-care agency and therapeutic self-care demand", "The regulator and cognator subsystems", "The core structure and flexible line of defense"]'::jsonb, 2, 'Roy identifies the regulator subsystem, which responds automatically through neural, chemical, and endocrine processes, and the cognator subsystem, which responds through cognitive-emotive channels such as perception, learning, judgment, and emotion.', 'Research & Nursing Process'),
(136, 'Nursing Process & Nursing Theories', 'Gordon''s framework organizes assessment data into how many functional health patterns?', '["11", "5", "9", "14"]'::jsonb, 0, 'Gordon''s Functional Health Patterns framework consists of 11 categories, ranging from health perception-health management to value-belief patterns.', 'Research & Nursing Process'),
(137, 'Nursing Process & Nursing Theories', 'Abraham Maslow''s hierarchy of needs is typically depicted as a pyramid with which level at the very base, representing the most fundamental needs?', '["Love and belonging needs", "Safety and security needs", "Physiological needs", "Self-actualization needs"]'::jsonb, 2, 'Physiological needs, such as oxygen, food, water, and elimination, form the base of Maslow''s pyramid because they must generally be met first to sustain life before higher-level needs can be addressed.', 'Research & Nursing Process'),
(138, 'Nursing Process & Nursing Theories', 'A nurse is caring for four clients simultaneously. Which client''s need should the nurse prioritize FIRST according to Maslow''s hierarchy of needs?', '["A client expressing embarrassment about needing help with bathing", "A client requesting a chaplain visit for spiritual support", "A client worried about being discharged without family support", "A client with an oxygen saturation of 84% on room air"]'::jsonb, 3, 'A critically low oxygen saturation represents an urgent physiological need (oxygenation) that takes priority over safety, love/belonging, and esteem needs according to Maslow''s hierarchy.', 'Research & Nursing Process'),
(139, 'Nursing Process & Nursing Theories', 'Which nurse theorist first introduced the term "nursing process" into nursing literature?', '["Virginia Henderson", "Lydia Hall", "Dorothea Orem", "Ida Jean Orlando"]'::jsonb, 1, 'Lydia Hall coined the term "nursing process" in 1955, marking one of the earliest uses of the phrase in nursing literature.', 'Research & Nursing Process'),
(140, 'Nursing Process & Nursing Theories', 'The addition of "Nursing Diagnosis" as a distinct fifth step of the nursing process is most closely associated with which development?', '["Publication of Florence Nightingale''s Notes on Nursing", "The founding of the National Conference Group (later NANDA) in 1973", "The Nurse Practice Act of 1938", "The introduction of SMART goal criteria"]'::jsonb, 1, 'The 1973 National Conference on Classification of Nursing Diagnoses, which led to NANDA, formally established nursing diagnosis as a distinct step, expanding the process from four to five phases (ADPIE).', 'Research & Nursing Process'),
(141, 'Nursing Process & Nursing Theories', 'Which characteristic of the nursing process reflects the requirement that care be tailored to each individual rather than applied uniformly?', '["Interpersonal nature", "Client-centeredness", "Systematic organization", "Universality"]'::jsonb, 1, 'Client-centeredness (individualization) means the plan of care is built around the specific client''s needs, values, and responses rather than a one-size-fits-all approach.', 'Research & Nursing Process'),
(142, 'Nursing Process & Nursing Theories', 'A client reports, "I have a throbbing headache that is a 7 out of 10." This is an example of which type of data?', '["Subjective data", "Validated data", "Objective data", "Secondary data"]'::jsonb, 0, 'Subjective data (symptoms) are information reported directly by the client, such as pain descriptions, and cannot be independently observed or measured by the nurse.', 'Research & Nursing Process'),
(143, 'Nursing Process & Nursing Theories', 'The client is the ____ source of data, while the client''s chart, family members, and other health professionals are ____ sources.', '["unreliable; reliable", "primary; secondary", "primary; tertiary", "secondary; primary"]'::jsonb, 1, 'The client is always the primary source of data because information comes directly from them; the chart, family, and other professionals are secondary sources.', 'Research & Nursing Process'),
(144, 'Nursing Process & Nursing Theories', 'Which physical examination technique uses tapping on the body surface to assess underlying structures based on the sound produced (e.g., dullness vs resonance)?', '["Inspection", "Auscultation", "Palpation", "Percussion"]'::jsonb, 3, 'Percussion involves tapping body surfaces to produce sounds, such as resonance or dullness, that reveal information about underlying structures.', 'Research & Nursing Process'),
(145, 'Nursing Process & Nursing Theories', 'What is the correct sequence of physical examination techniques when assessing the abdomen, and why does it differ from other body systems?', '["Inspection, palpation, percussion, auscultation — because palpation stimulates bowel sounds", "Inspection, auscultation, percussion, palpation — because palpation and percussion can alter bowel motility and sounds before they can be auscultated", "Percussion, palpation, inspection, auscultation", "Auscultation, inspection, palpation, percussion — because auscultation must always come first"]'::jsonb, 1, 'For the abdomen, auscultation is performed before palpation and percussion because manipulating the abdomen can artificially stimulate or alter bowel sounds, distorting findings.', 'Research & Nursing Process'),
(146, 'Nursing Process & Nursing Theories', 'A nurse rapidly assesses an unresponsive trauma patient''s airway, breathing, and circulation. This is an example of what type of assessment?', '["Emergency assessment", "Focused assessment", "Time-lapsed reassessment", "Initial comprehensive assessment"]'::jsonb, 0, 'An emergency assessment is a rapid, focused evaluation of life-threatening problems such as airway, breathing, and circulation, prioritized over a full comprehensive assessment.', 'Research & Nursing Process'),
(147, 'Nursing Process & Nursing Theories', 'A nurse compares a client''s current status to data obtained several months ago during a scheduled follow-up visit. This type of assessment is called:', '["Initial assessment", "Time-lapsed reassessment", "Focused assessment", "Emergency assessment"]'::jsonb, 1, 'A time-lapsed reassessment compares a client''s current status to previously collected baseline data, typically during scheduled follow-up care.', 'Research & Nursing Process'),
(148, 'Nursing Process & Nursing Theories', 'A nurse writes the diagnosis "Risk for Infection related to presence of invasive central venous catheter." Which type of nursing diagnosis is this?', '["Possible", "Actual", "Risk", "Syndrome"]'::jsonb, 2, 'A risk nursing diagnosis describes a health problem that does not yet exist but that the client is particularly vulnerable to developing due to identifiable risk factors.', 'Research & Nursing Process'),
(149, 'Nursing Process & Nursing Theories', '"Rape-Trauma Syndrome" and "Disuse Syndrome" are examples of which type of nursing diagnosis?', '["Risk diagnosis", "Actual diagnosis", "Syndrome diagnosis", "Health promotion diagnosis"]'::jsonb, 2, 'A syndrome diagnosis is a clinical judgment concerning a cluster of actual or risk nursing diagnoses predicted to occur together due to a certain event or situation.', 'Research & Nursing Process'),
(150, 'Nursing Process & Nursing Theories', 'In the standard PES format for writing an actual nursing diagnosis, what does the "E" represent?', '["Emergency status", "Evaluation", "Examination findings", "Etiology (related factors)"]'::jsonb, 3, 'In PES format, "E" stands for etiology, the related factor(s) contributing to the problem.', 'Research & Nursing Process'),
(151, 'Nursing Process & Nursing Theories', 'Which of the following diagnostic statements contains an error because the etiology names something that cannot legally or ethically be documented as a "cause" by a nurse?', '["\"Impaired Skin Integrity related to inadequate nursing care\"", "\"Ineffective Coping related to situational crisis\"", "\"Risk for Falls related to unsteady gait\"", "\"Acute Pain related to surgical incision\""]'::jsonb, 0, 'Writing a diagnosis with an etiology that implicates staff negligence, such as "related to inadequate nursing care," is legally inadvisable and inappropriate.', 'Research & Nursing Process'),
(152, 'Nursing Process & Nursing Theories', 'Which of the following best describes a "collaborative problem" as distinguished from a nursing diagnosis?', '["A diagnosis exclusively determined by the physician", "A synonym for an actual nursing diagnosis", "A problem that the nurse manages independently using nursing interventions alone", "A potential physiological complication that nurses monitor and manage using interventions prescribed by both nursing and medicine"]'::jsonb, 3, 'Collaborative problems, per Carpenito''s model, are potential physiological complications nurses monitor, managed using both physician-prescribed and nursing-prescribed interventions, unlike independently treatable nursing diagnoses.', 'Research & Nursing Process'),
(153, 'Nursing Process & Nursing Theories', 'When a nurse writes "Impaired Gas Exchange related to Impaired Gas Exchange," what diagnostic error has occurred?', '["This is a \"circular\" statement, in which the etiology restates the problem rather than identifying its cause", "This is an example of a wellness diagnosis", "The statement correctly follows the PES format", "This is an example of a syndrome diagnosis"]'::jsonb, 0, 'A circular (tautological) statement occurs when the etiology simply repeats the problem, providing no useful information for planning interventions to address the cause.', 'Research & Nursing Process'),
(154, 'Nursing Process & Nursing Theories', 'What does the "S" in SMART goal criteria stand for?', '["Standard", "Specific", "Subjective", "Simple"]'::jsonb, 1, 'In SMART goal criteria, "S" stands for Specific — the goal must clearly state exactly what is to be achieved.', 'Research & Nursing Process'),
(155, 'Nursing Process & Nursing Theories', 'A nurse writes: "Nurse will teach the client about insulin administration." What is wrong with this outcome statement?', '["It describes a nursing intervention/action, not a measurable client outcome", "Nothing; it is a correctly written outcome", "It is too specific", "It lacks a time frame only"]'::jsonb, 0, 'Outcome statements must describe an expected client behavior or response, not a nursing action; "nurse will teach" is an intervention, not a client outcome.', 'Research & Nursing Process'),
(156, 'Nursing Process & Nursing Theories', 'In the acronym RUMBA, sometimes used alongside SMART to evaluate outcome statements, what does the "M" represent?', '["Multidisciplinary", "Motivating", "Measurable", "Mandatory"]'::jsonb, 2, 'In RUMBA (Relevant, Understandable, Measurable, Behavioral, Achievable), the "M" stands for Measurable.', 'Research & Nursing Process'),
(157, 'Nursing Process & Nursing Theories', 'A nurse administers a prescribed antibiotic according to the physician''s order. This is an example of which type of nursing intervention?', '["Unauthorized intervention", "Interdependent (collaborative) intervention", "Dependent intervention", "Independent intervention"]'::jsonb, 2, 'Administering a medication per a physician''s order is a dependent intervention, since it requires a prescriber''s order to carry out.', 'Research & Nursing Process'),
(158, 'Nursing Process & Nursing Theories', 'Discharge planning should ideally begin:', '["Only after the physician writes the discharge order", "On the day of discharge only", "Only if the client requests it", "At the time of admission and continuing throughout the hospital stay"]'::jsonb, 3, 'Effective discharge planning begins at admission and continues throughout the hospital stay to ensure a safe, well-prepared transition.', 'Research & Nursing Process'),
(159, 'Nursing Process & Nursing Theories', 'A critical pathway (care map) used in an ICU for post-cardiac-surgery clients is BEST described as:', '["A document that replaces the need for nursing assessment", "A standardized, multidisciplinary plan outlining the sequence and timing of interventions expected to achieve outcomes within a specific time frame", "A tool used exclusively for billing purposes", "A plan used only for clients with no comorbidities"]'::jsonb, 1, 'A critical pathway is a standardized, multidisciplinary plan that sequences expected interventions and outcomes over a defined time frame for a specific condition or procedure.', 'Research & Nursing Process'),
(160, 'Nursing Process & Nursing Theories', 'A nurse delegates the task of ambulating a stable postoperative client to a nursing assistant. Which principle of delegation is MOST important for the registered nurse to apply?', '["Delegating without providing any instructions", "Avoiding all delegation regardless of task complexity", "Ensuring the task is within the delegatee''s scope of practice/competency and does not require nursing judgment", "Delegating tasks that require independent nursing judgment"]'::jsonb, 2, 'Safe delegation requires confirming the task is within the delegatee''s scope and competency and does not require independent nursing judgment.', 'Research & Nursing Process'),
(161, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which of the following is NOT an exercise-prescription variable?', '["Intensity", "Progression", "Gender", "Duration"]'::jsonb, 2, 'Exercise prescription is described by FITT-type variables: frequency, intensity, time (duration), type, and progression. Gender is a patient characteristic, not a prescription variable.', 'Mixed Revision'),
(162, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which of the following is an example of a balance and coordination exercise?', '["Kegel exercise", "Ballistic stretching", "Squatting exercise", "Frenkel''s exercises"]'::jsonb, 3, 'Frenkel''s exercises are a graded series of slow, repetitive movements used to improve coordination and balance (e.g. in ataxia). Kegel exercises strengthen the pelvic floor; squats build strength; ballistic stretching is a flexibility technique.', 'Mixed Revision'),
(163, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Passive exercise is used clinically mainly to:', '["Increase muscle tone", "Increase muscle power", "Increase muscle strength", "Maintain joint range of motion"]'::jsonb, 3, 'In passive range-of-motion exercise the therapist or nurse moves the joint without the patient''s muscle effort, so it maintains joint mobility and prevents contractures but does not build strength or power.', 'Mixed Revision'),
(164, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which technique is used for airway clearance and lung inflation in a ventilated ICU patient?', '["Manual hyperinflation", "Inspiratory muscle training", "Diaphragmatic breathing", "Pursed-lip breathing"]'::jsonb, 0, 'Manual hyperinflation (bagging with slow deep breaths, an inspiratory pause and quick release) re-expands collapsed alveoli and moves secretions toward the large airways. The other options need an awake, cooperative patient.', 'Mixed Revision'),
(165, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which of the following is NOT a barrier to early mobilisation in the ICU?', '["The patient''s gender", "Co-morbidities", "Physiological instability", "The ICU environment (lines, tubes, equipment)"]'::jsonb, 0, 'Recognised barriers include haemodynamic/respiratory instability, sedation, co-morbidities, attached devices, staffing and the ICU environment. Gender is not a barrier.', 'Mixed Revision'),
(166, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Decreased orthostatic tolerance after prolonged bed rest is characterised by:', '["Cerebral hyperaemia", "A fall in heart rate on standing", "Hypertension on standing", "Dizziness or faintness when the patient suddenly sits or stands up"]'::jsonb, 3, 'After bed rest, blood volume and baroreflex responsiveness fall, so blood pools in the legs on standing, causing orthostatic hypotension: dizziness, faintness and a compensatory rise in heart rate.', 'Mixed Revision'),
(167, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which statement about the Oxford (MRC) scale for grading muscle power is FALSE?', '["Grade 0 means no contraction at all", "It is used to measure muscle strength", "Grade 5 means movement against gravity only", "It grades power from 0 to 5"]'::jsonb, 2, 'Grade 3 is full movement against gravity only; grade 4 is movement against gravity and some resistance; grade 5 is normal power against full resistance.', 'Mixed Revision'),
(168, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'The effects of prolonged immobility on the musculoskeletal system include all of the following EXCEPT:', '["Increased muscle mass", "Joint contracture", "Decreased joint stability", "Reduced muscle endurance"]'::jsonb, 0, 'Immobility causes disuse atrophy (loss of muscle mass), weakness, reduced endurance, contractures, bone demineralisation and joint instability — not an increase in muscle mass.', 'Mixed Revision'),
(169, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which of the following is NOT a therapeutic (physiotherapy) modality?', '["Cryotherapy", "X-ray machine", "Transcutaneous electrical nerve stimulator (TENS)", "Therapeutic ultrasound"]'::jsonb, 1, 'Cryotherapy, therapeutic ultrasound and TENS are physical agents used for treatment. An X-ray machine is a diagnostic imaging device.', 'Mixed Revision'),
(170, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Accidental displacement of a chest drain while turning a patient may cause:', '["Pneumothorax", "Internal bleeding", "Pneumonia", "Atelectasis only"]'::jsonb, 0, 'If the drain is pulled out or its holes leave the chest, air can enter the pleural space and the lung may collapse (pneumothorax). Secure the tube before turning; if it falls out, cover the site with an occlusive dressing and call for help.', 'Mixed Revision'),
(171, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'The head-down (Trendelenburg) position used for postural drainage may cause which complication?', '["Raised intracranial pressure", "Deep vein thrombosis", "Neck fracture", "Air embolism"]'::jsonb, 0, 'Head-down tilt reduces cerebral venous drainage and raises intracranial pressure, so it is avoided in head injury, raised ICP, recent neurosurgery, uncontrolled hypertension and gross abdominal distension.', 'Mixed Revision'),
(172, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'An important adverse effect of manual hyperinflation (bagging) is:', '["Hypoglycaemia", "Increased intracranial compliance", "Pneumothorax", "Pulmonary embolism"]'::jsonb, 2, 'Large manual breaths can over-distend alveoli and cause barotrauma, including pneumothorax, and can reduce venous return and blood pressure. Use a manometer and limit peak pressures.', 'Mixed Revision'),
(173, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which of the following contraceptive methods does NOT protect against sexually transmitted infections (STIs)?', '["Combined oral contraceptive pill", "Abstinence", "Male condom", "Female condom"]'::jsonb, 0, 'Only barrier methods (male and female condoms) and abstinence reduce STI transmission. Hormonal methods such as the pill prevent pregnancy but give no protection against STIs, including HIV.', 'Mixed Revision'),
(174, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'What is the purpose of emergency contraception?', '["To treat infertility", "To terminate an established pregnancy", "To regulate menstrual cycles", "To prevent pregnancy after unprotected intercourse"]'::jsonb, 3, 'Emergency contraception (levonorgestrel or ulipristal pills, or a copper IUD) is used after unprotected sex or contraceptive failure to prevent pregnancy. It does not end an established pregnancy.', 'Mixed Revision'),
(175, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'What is the purpose of male condoms in family planning?', '["Preventing pregnancy", "Reducing the risk of STIs", "Both A and B", "None of the above"]'::jsonb, 2, 'Used correctly and consistently, the male condom is the only male method that both prevents pregnancy and reduces transmission of STIs, including HIV.', 'Mixed Revision'),
(176, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'How does a copper intrauterine device (IUD) mainly prevent pregnancy?', '["By thinning the endometrium through hormone release", "By causing abortion of the implanted embryo", "By creating a uterine environment that is toxic to sperm, preventing fertilisation", "By inhibiting ovulation"]'::jsonb, 2, 'Copper ions cause a local inflammatory reaction that is toxic to sperm and ova, so fertilisation is prevented. The copper IUD contains no hormones and does not stop ovulation.', 'Mixed Revision'),
(177, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'What is the main mechanism of action of emergency contraceptive pills (e.g. levonorgestrel)?', '["Killing sperm in the vagina", "Delaying or preventing ovulation", "Inducing an abortion", "Destroying an implanted embryo"]'::jsonb, 1, 'Levonorgestrel and ulipristal emergency pills work mainly by delaying or preventing ovulation; they do not disrupt an established pregnancy. That is why they work best when taken as soon as possible.', 'Mixed Revision'),
(178, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'What is considered the most effective form of emergency contraception?', '["Copper IUD", "Diaphragm", "Condoms", "Levonorgestrel emergency pill"]'::jsonb, 0, 'A copper IUD inserted within 5 days of unprotected intercourse is over 99% effective and then continues as long-term contraception. Emergency pills are less effective, especially as time passes.', 'Mixed Revision'),
(179, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'If a woman becomes pregnant while using an IUD, which complication should be suspected and excluded?', '["Twin pregnancy", "Pre-eclampsia", "Ectopic pregnancy", "Gestational diabetes"]'::jsonb, 2, 'IUDs prevent intrauterine pregnancy very effectively, so if pregnancy does occur a higher proportion are ectopic. An ectopic pregnancy must be excluded urgently.', 'Mixed Revision'),
(180, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'How long does one injection of DMPA (Depo-Provera, 150 mg IM) protect against pregnancy?', '["6 months", "1 month", "3 months", "1 year"]'::jsonb, 2, 'DMPA 150 mg is given every 12–13 weeks (3 months). Noristerat (NET-EN) is given every 2 months; monthly combined injectables every 4 weeks.', 'Mixed Revision'),
(181, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which barrier method is suitable for a couple when one partner has a latex allergy?', '["Male latex condom", "Latex diaphragm", "None — barrier methods cannot be used", "Female condom (nitrile/polyurethane)"]'::jsonb, 3, 'Female condoms are made of nitrile or polyurethane, not latex, so they suit people with latex allergy (polyurethane male condoms are another option).', 'Mixed Revision'),
(182, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'How does the fertility-awareness (natural family planning) method identify fertile days?', '["By monitoring changes in cervical mucus", "By daily basal body temperature charting", "Both A and B", "None of the above"]'::jsonb, 2, 'The symptothermal method combines cervical mucus changes (clear, stretchy mucus near ovulation) with a sustained rise in basal body temperature after ovulation, often with calendar calculation.', 'Mixed Revision'),
(183, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'In a central venous pressure (CVP) waveform, the ''a'' wave represents:', '["Atrial relaxation", "Ventricular relaxation", "Atrial contraction", "Ventricular contraction"]'::jsonb, 2, 'The a wave is right atrial contraction (after the P wave on the ECG). The c wave is tricuspid closure/bulging, the x descent atrial relaxation, the v wave atrial filling, and the y descent atrial emptying.', 'Mixed Revision'),
(184, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'In a pulmonary artery pressure waveform, the dicrotic notch represents:', '["Opening of the mitral valve", "The peak of ventricular systole", "Closure of the pulmonary valve", "Closure of the tricuspid valve"]'::jsonb, 2, 'The dicrotic notch on the PA trace marks pulmonic valve closure at the end of right ventricular ejection (on an arterial trace it marks aortic valve closure).', 'Mixed Revision'),
(185, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Cardiac output is calculated as:', '["Blood pressure ÷ heart rate", "Blood pressure × heart rate", "Stroke volume × heart rate", "Stroke volume ÷ heart rate"]'::jsonb, 2, 'CO = SV × HR (normal about 4–8 L/min). For example, 70 mL × 72 beats/min ≈ 5 L/min.', 'Mixed Revision'),
(186, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'When levelling and zeroing an arterial or CVP transducer, it should be placed at the:', '["Any level, as it does not matter", "Phlebostatic axis (4th intercostal space, mid-axillary line)", "Level of the head", "Level of the feet"]'::jsonb, 1, 'The phlebostatic axis approximates the level of the right atrium. A transducer placed too low gives falsely high readings; placed too high gives falsely low readings.', 'Mixed Revision'),
(187, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Right ventricular preload is best estimated at the bedside by:', '["Central venous pressure (CVP)", "Mean arterial pressure (MAP)", "Cardiac output (CO)", "Systemic vascular resistance (SVR)"]'::jsonb, 0, 'Preload is end-diastolic stretch. CVP (right atrial pressure) is used to estimate right-sided preload; PAWP estimates left-sided preload. SVR reflects afterload.', 'Mixed Revision'),
(188, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'What is the normal range for systemic vascular resistance (SVR) in an adult?', '["800–1200 dyn·s·cm⁻⁵", "1600–2000 dyn·s·cm⁻⁵", "400–600 dyn·s·cm⁻⁵", "200–400 dyn·s·cm⁻⁵"]'::jsonb, 0, 'Normal SVR is about 800–1200 dyn·s·cm⁻⁵. It is high in vasoconstriction (cardiogenic or hypovolaemic shock) and low in vasodilation (septic or anaphylactic shock).', 'Mixed Revision'),
(189, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'A patient has a low cardiac output with a high systemic vascular resistance and adequate filling pressures. Which therapy is most appropriate to improve output?', '["Beta-blockers", "Vasodilators (afterload reduction)", "Vasopressors", "Rapid fluid boluses"]'::jsonb, 1, 'High SVR means high afterload, which the failing heart cannot pump against. Reducing afterload with vasodilators (e.g. nitrates, nitroprusside), often with an inotrope, increases stroke volume. Vasopressors would raise afterload further.', 'Mixed Revision'),
(190, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which is a key intervention to prevent ventilator-associated pneumonia (VAP)?', '["Elevating the head of the bed 30–45°", "Daily chest X-rays", "Prophylactic antibiotics for all ventilated patients", "Routine 2-hourly suctioning whether needed or not"]'::jsonb, 0, 'Head-of-bed elevation reduces aspiration of gastric contents and oropharyngeal secretions. It is part of the VAP bundle with daily sedation hold and readiness-to-wean assessment, oral care, subglottic suction, cuff pressure 20–30 cmH₂O and avoiding unnecessary circuit changes.', 'Mixed Revision'),
(191, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which organism is commonly associated with late-onset ventilator-associated pneumonia in the ICU?', '["Clostridium tetani", "Neisseria meningitidis", "Streptococcus pyogenes", "Pseudomonas aeruginosa"]'::jsonb, 3, 'Late-onset VAP (≥5 days) is often caused by multidrug-resistant Gram-negative bacilli such as Pseudomonas aeruginosa, Acinetobacter and Klebsiella, and by MRSA.', 'Mixed Revision'),
(192, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'A patient is suspected of carrying a multidrug-resistant organism (MDRO). What is the FIRST infection-control action?', '["Remove all invasive devices", "Transfer the patient to another hospital", "Start broad-spectrum antibiotics", "Implement contact precautions"]'::jsonb, 3, 'Contact precautions (single room or cohorting, gloves and gown, dedicated equipment, strict hand hygiene) are started immediately to prevent spread while cultures are confirmed.', 'Mixed Revision'),
(193, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which practice is a key principle of antimicrobial stewardship?', '["De-escalating to a narrower-spectrum antibiotic once culture results are known", "Using broad-spectrum antibiotics for as long as possible", "Avoiding cultures before starting antibiotics", "Prolonging every course of antibiotics"]'::jsonb, 0, 'Stewardship means the right drug, dose, route and duration: take cultures first, start appropriate empirical therapy, then de-escalate or stop according to results, to limit resistance and side effects.', 'Mixed Revision'),
(194, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which measure helps prevent central line-associated bloodstream infection (CLABSI)?', '["Routine replacement of central lines every 48 hours", "Skin antisepsis with chlorhexidine (2% in alcohol)", "Using the femoral site in preference to all others", "Leaving an unneeded line in place ''just in case''"]'::jsonb, 1, 'The CLABSI bundle: hand hygiene, maximal sterile barrier precautions, chlorhexidine skin antisepsis, avoiding the femoral site where possible, and daily review with prompt removal of unnecessary lines. Routine scheduled line changes are not recommended.', 'Mixed Revision'),
(195, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'What is the usual target Richmond Agitation–Sedation Scale (RASS) score for a lightly sedated ICU patient?', '["+1 to +2", "−5 to −4", "−2 to 0", "+3 to +4"]'::jsonb, 2, 'Light sedation (RASS 0 to −2: alert and calm to briefly awakening to voice) is associated with shorter ventilation and less delirium. −4/−5 is deep sedation; positive scores indicate agitation.', 'Mixed Revision'),
(196, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which sedative causes the LEAST respiratory depression?', '["Fentanyl", "Midazolam", "Dexmedetomidine", "Propofol"]'::jsonb, 2, 'Dexmedetomidine, an alpha-2 agonist, gives ''cooperative'' sedation with minimal respiratory depression. Watch for bradycardia and hypotension.', 'Mixed Revision'),
(197, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which group of drugs should generally be avoided when managing ICU delirium?', '["Dexmedetomidine", "Benzodiazepines", "Antipsychotics such as haloperidol", "Atypical antipsychotics such as quetiapine"]'::jsonb, 1, 'Benzodiazepines are an independent risk factor for ICU delirium and can worsen it. The exception is alcohol or benzodiazepine withdrawal.', 'Mixed Revision'),
(198, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'The diaphragm, the main muscle of breathing, is supplied by the:', '["Brachial plexus", "Phrenic nerve", "Sciatic nerve", "Vagus nerve"]'::jsonb, 1, 'The phrenic nerve arises from C3–C5 (''C3, 4, 5 keeps the diaphragm alive''). High cervical cord injury above C3 therefore causes respiratory paralysis.', 'Mixed Revision'),
(199, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'The volume of air remaining in the lungs after a maximal forced expiration is the:', '["Inspiratory reserve volume", "Residual volume", "Tidal volume", "Expiratory reserve volume"]'::jsonb, 1, 'Residual volume (about 1.2 L) cannot be exhaled; it keeps alveoli open between breaths. It rises in obstructive disease such as emphysema (air trapping).', 'Mixed Revision'),
(200, 'Reproductive Health, Physiotherapy, Haemodynamics, Infection Control & Sedation', 'Which of the following is NOT part of the conducting zone of the respiratory system?', '["Bronchi", "Terminal bronchioles", "Trachea", "Alveoli"]'::jsonb, 3, 'The conducting zone (nose to terminal bronchioles) moves, warms and humidifies air and is anatomical dead space. Gas exchange happens in the respiratory zone: respiratory bronchioles, alveolar ducts and alveoli.', 'Mixed Revision');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
